function validate([stones, k]) {
  if (!Array.isArray(stones) || stones.length < 1 || stones.length > 30) return 'stones needs 1 to 30 piles.';
  if (stones.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each pile holds 1 to 100 stones.';
  if (!Number.isInteger(k) || k < 2 || k > 30) return 'k is between 2 and 30.';
  return null;
}

