function mergeStones(stones, k) {
  const n = stones.length;
  if ((n - 1) % (k - 1) !== 0) {
    return -1;
  }
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + stones[i];
  }
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let len = k; len <= n; len++) {
    for (let left = 0; left + len <= n; left++) {
      const right = left + len - 1;
      dp[left][right] = Infinity;
      for (let mid = left; mid < right; mid += k - 1) {
        dp[left][right] = Math.min(dp[left][right], dp[left][mid] + dp[mid + 1][right]);
      }
      if ((len - 1) % (k - 1) === 0) {
        dp[left][right] += prefix[right + 1] - prefix[left];
      }
    }
  }
  return dp[0][n - 1];
}

