function mergeStones(stones, k) {
  // Try every possible move from every reachable row of piles, remembering rows already solved.
  const memo = new Map();
  const solve = (piles) => {
    if (piles.length === 1) return 0;
    const key = piles.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = -1;
    for (let i = 0; i + k <= piles.length; i++) {
      let merged = 0;
      for (let j = i; j < i + k; j++) merged += piles[j];
      const rest = solve([...piles.slice(0, i), merged, ...piles.slice(i + k)]);
      if (rest >= 0 && (best < 0 || merged + rest < best)) best = merged + rest;
    }
    memo.set(key, best);
    return best;
  };
  return solve(stones);
}

