function generate(rand, size) {
  if (size === 'large') {
    const k = 2 + Math.floor(rand() * 29);
    // Mostly the longest row that can be merged; sometimes 30 piles, which may be impossible.
    const n = rand() < 0.8 ? 1 + Math.floor(29 / (k - 1)) * (k - 1) : 30;
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 100)), k];
  }
  const k = 2 + Math.floor(rand() * 3);
  // Half of the small rows have a length that can reach one pile.
  const n = rand() < 0.5 ? 1 + Math.floor(rand() * 9) : 1 + (k - 1) * Math.floor(rand() * (8 / (k - 1) + 1));
  const top = rand() < 0.3 ? 3 : 100;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top)), k];
}
